(function(L){
'use strict';var A=L.A;
function c(n){return 'c9-'+n+'-core';}
function ss(n){return ['TB9:9.'+n];}
function topic(n){return n<=3?'E2T13':(n===4||n===9)?'E2T14':(n>=5&&n<=7)?'E2T15':(n===8||n===10||n===11||n===12)?'E2T16':'E2T17';}
function ex(n,more){return Object.assign({examId:'exam2',mock:false,topics:[topic(n)],sourceSection:'9.'+n,connectAssessment:true},more||{});}
function image(n,cap,alt){return {kind:'img',src:'assets/figures/connect-ch9-assessment/'+n+'.png',cap:cap,alt:alt};}
var M={siccar:[image('siccar','Textbook equivalent · 09.00.a2','Siccar Point exposure with contrasting gray and reddish beds.')],intrusion:[image('intrusion','Textbook equivalent · 09.01.a12','Dark igneous body between lighter rocks with reddish margins.')],lava:[image('surface-lava','Textbook equivalent · 09.02.b2','Original block showing lava covering part of a landscape.')],basement:[image('basement-contact','Textbook equivalent · 09.03.b3','Original labeled contact photograph; identify event order, not the printed name.')],iron:[image('banded-rock','Textbook equivalent · 09.10.c3','Finely banded reddish and gray rock with a coin for scale.')],correlation:[image('correlation','Textbook equivalent · 09.13.a1','Two original stratigraphic columns with dashed correlations.') ]};
function card(n,id,h,groups,trap,media,sources){A.cards('c9s'+n,[{id:'g-c9q-'+id,h:h,c:[c(n)],html:groups.map(g=>'<h4>'+g[0]+'</h4><ul>'+g[1].map(p=>'<li>'+p+'</li>').join('')+'</ul>').join(''),src:sources||ss(n),media:media||[],traps:[trap],examId:'exam2'}]);}
card(3,'siccar','Siccar Point: two rock packages, different histories',[
 ['Read the contact',['Gray sandstone and shale below the contact were deposited, tilted toward vertical, and eroded before reddish sandstone and conglomerate accumulated above them.','The younger deposits include fragments of the older gray rocks. Different orientations and the truncated lower beds record more than one episode.']],
 ['Use the right visual evidence',['The image here is the original textbook close-up. The supplied assessment captures show a broken image placeholder, so their unseen figure cannot be checked for exact visual equivalence.']]
],'Different rock histories do not supply an exact elapsed time by themselves.',M.siccar,['TB9:9.0','TB9:9.3']);
card(1,'principles','Choose the principle that matches the observation',[
 ['Orientation and order',['Original horizontality says most sediments begin in approximately horizontal layers. Tilted or folded beds normally record later deformation; exceptions include dune faces and delta slopes.','Superposition compares positions in an undisturbed depositional stack: younger layers form above older layers. Uplift does not necessarily tilt a bed.']],
 ['Intrusions and contacts',['A dike that cuts a host rock is younger by cross-cutting relations. Baking or alteration of the host beside magma independently gives a contact-effects relation.','Inclusions concern pieces of older material enclosed within a younger rock. Do not use superposition as a substitute for cross-cutting simply because an intrusive body is visible.']],
 ['A supplied feedback conflict',['Assessment Q3 marks “contact effects; superposition” correct for a dike-intrusion stem and marks “cross-cutting relations; contact effects” incorrect. Its figure did not render. The textbook explicitly supports cross-cutting and contact effects for an intrusion cutting and baking its host. Practice here states those observations directly; the original feedback conflict remains unresolved.']]
],'Select a principle from the actual relationship, not a memorized option pair.',M.intrusion);
card(2,'surface','A surface predates what covers it',[
 ['Lava and the landscape',['The depicted lava lies on an existing landscape surface. The covered surface therefore existed before that eruption.','A dated lava can constrain the age of the surface beneath it, but it does not date every older episode that shaped that landscape.']]
],'A lava blanket is younger than its substrate, not older.',M.lava);
card(3,'gaps','Expose, erode, then bury: interpreting gaps',[
 ['Granite below sandstone',['Granite must crystallize at depth, then become exposed through uplift and removal of overlying rock before sediment is deposited directly on its eroded surface.','The original labeled photograph is useful for reconstructing events. Its printed “nonconformity” label is a teaching reference, not a hidden identification answer.']],
 ['Similar limestone can conceal missing time',['A disconformity separates essentially parallel sedimentary layers and records an interval of nondeposition and/or erosion. The rocks above and below can look very similar.','Compare their fossil assemblages and established fossil ranges to test for an age gap. Similar mineral content, porosity, or fracture orientation alone does not establish continuous deposition.']]
],'A contact can represent missing time even when the beds above and below are parallel.',M.basement,['TB9:9.3','TB9:9.7']);
card(5,'fossils','Fossils versus mineral lookalikes',[
 ['Body and trace evidence',['Preserved leaves and other body remains are fossils. Footprints and sediment-filled burrows record biological activity and are trace fossils.','Dendrites are branching mineral growths, commonly manganese oxides along fractures or bedding. Their plant-like shape does not make them fossils.']]
],'A branching outline is not sufficient evidence of a preserved organism.');
card(7,'overlap','An assemblage narrows an age interval',[
 ['Use the intersection of ranges',['A layer containing several contemporaneous fossil species must fit the interval during which their ranges overlap. A combination can constrain age more narrowly than any one long-ranging species.','This interpretation assumes the fossils belong to the deposit rather than having been eroded from older rocks and redeposited. The full ranges and geologic context matter.']]
],'The combined age is the shared overlap, not the sum or union of species ranges.');
card(8,'time','Place the large time divisions in order',[
 ['Oldest to youngest',['Precambrian time precedes the Cambrian and the abundant hard-part fossil record emphasized in the course. It does not mean there was no earlier life.','The large sequence is <b>Precambrian → Paleozoic → Mesozoic → Cenozoic</b>. Paleozoic, Mesozoic, and Cenozoic are eras; Precambrian is a broader informal interval containing several eons.']],
 ['Connect chart limitation',['The assessment’s A–D chart did not render. Its checked D response cannot establish where D was drawn. Learn the temporal relation here without inventing the missing geometry.']]
],'Before abundant hard parts is not the same as before all organisms.');
card(11,'cambrian','The Cambrian explosion is biological',[
 ['What changed',['The course describes a geologically rapid diversification and widespread appearance of organisms with shells or other hard protective parts at the beginning of the Cambrian.','The textbook places this at about 541 Ma and describes changes over roughly 20–30 million years. “Explosion” is not a volcanic blast, and it was not the origin of all life.']]
],'Use the supplied textbook’s dates for this course; the term describes evolutionary change.');
card(9,'records','Annual records and ancient minerals answer different questions',[
 ['Count repeated seasons',['Tree growth rings, annual ice layers, and lake varves can preserve repeated yearly cycles. A varve includes the alternating seasonal sediment layers representing one year.','Count complete annual cycles, not every light or dark stripe as a separate year. Identify gaps or disturbed records before assuming an uninterrupted count.']],
 ['The oldest material is Precambrian',['The textbook describes approximately 4.0-billion-year-old Acasta Gneiss in Canada and still older individual zircon grains, including Australian material, up to about 4.4 billion years.','A grain’s crystallization age, the age of its present host rock, and the age of Earth are different targets. These ancient dates fall in Precambrian time.']]
],'An old inherited grain does not automatically date the deposition of the rock containing it.');
card(10,'early-earth','Impact shapes and oxygenation evidence',[
 ['Simple and complex craters',['In the textbook model, a relatively small impact makes a simple crater. A larger impact can make a complex crater with a central peak.','Both kinds occur on the Moon. Shape is not a rule that every simple crater is younger, or that moons have only simple craters.']],
 ['From photosynthesis to iron formation',['Cyanobacteria release oxygen through photosynthesis. Oxygen entering the atmosphere and oceans changed which minerals could form and persist.','The pictured iron formation has red and gray bands, largely iron oxides and quartz. Dissolved iron oxidized and precipitated in ocean water. This differs from lava cooling or iron oxidation in a soil on land.']]
],'Identify a mechanism from minerals and context; color alone is not sufficient.',M.iron);
card(12,'mesozoic','The dinosaur interval',[
 ['Mesozoic context',['The Mesozoic is the course’s “age of dinosaurs.” Its periods, oldest to youngest, are Triassic, Jurassic, and Cretaceous.','The following Cenozoic is associated with the expansion of mammals. Do not confuse an era with one period within it.']]
],'Jurassic is part of the Mesozoic, not a separate era competing with it.');
card(13,'correlation','Correlate using the strongest available evidence',[
 ['Physical continuity first',['Where exposure permits, physically tracing a bed continuously between two sections is the surest evidence that it is the same unit.','Matching distinctive rock types, fossils, and position within a sequence supports correlation when continuity cannot be followed. Similar color or equal height alone can be misleading.']],
 ['Read the original columns',['The dashed connections in these textbook columns are interpreted correlations, not exposed rock connecting the columns. Corresponding units can have different thicknesses.']]
],'A dashed correlation on a drawing is an interpretation, not direct observation of continuous exposure.',M.correlation);
card(14,'origins','Combine dating strategies at human sites',[
 ['Relative and numerical evidence',['Superposition and inclusions apply to archaeological deposits as well as older rocks. A reused fragment predates the younger wall or deposit containing it.','Appropriately young organic remains can be dated with carbon-14. Older human-associated sequences can be constrained by interbedded volcanic rocks and fossil evidence.']],
 ['Match method to material and timescale',['The textbook places useful carbon-14 applications here in the hundreds to tens of thousands of years, not millions of years. Bones, wood, and charcoal preserve organic carbon; volcanic minerals supply other isotope systems.']]
],'Do not apply carbon-14 indiscriminately to million-year-old rocks or every archaeological object.');
card(15,'canyon','Specify which Grand Canyon unconformity',[
 ['Lower gap in the textbook history',['Basement rocks are approximately 1.7 billion years old; the lower late-Precambrian deposits are about 1.1 billion years old. The lower unconformity therefore represents about <b>600 million years</b> missing from this local rock record.','The younger upper unconformity is a different surface. Where surfaces merge westward, the combined Great Unconformity represents an even larger gap.']],
 ['Keep the quantities straight',['1.7 − 1.1 = 0.6 billion years = 600 million years. This gap is not the age of the modern canyon incision or the age of Earth.']]
],'Do not assign the 600-million-year value to every unconformity in the canyon.');
A.order('e2-c9q-01',c(3),'Use the original Siccar Point close-up and the stated rock relations: vertical gray beds lie below younger reddish deposits. Arrange the events from oldest to youngest.',['Deposition of the gray beds','Tilting of the gray beds','Erosion across the tilted gray beds','Deposition of the reddish beds'],'The older package had already been deposited, deformed and eroded when the younger red beds accumulated.',['TB9:9.0','TB9:9.3'],ex(3,{media:M.siccar,sourceFigure:true}));
A.mc('e2-c9q-02',c(1),'Broad sedimentary beds that originally accumulated nearly level now dip steeply. Which conclusion follows from original horizontality?',['The sediment must have begun as a steep cliff|Most beds begin approximately horizontal.','*A later event changed the beds’ orientation|Tilting or folding followed deposition.','The beds cannot have been uplifted|Uplift is compatible with later deformation.','The beds must have been completely melted|Melting is not required to tilt beds.'],'Original horizontality separates initial deposition from later orientation changes; it does not prohibit uplift or require melting.',ss(1),ex(1));
A.match('e2-c9q-03',c(1),'The source photograph shows an intrusion and altered host margins. Match the specified evidence to the dating principle; use each term once.',[['Dike cuts across preexisting host rock','Cross-cutting relations'],['Host rock was baked beside the hot intrusion','Contact effects'],['A younger sedimentary bed lies on an older bed','Superposition'],['Older rock fragments occur inside a younger deposit','Inclusions']],'For a dike cutting and baking its host, cross-cutting and contact effects independently establish that the intrusion is younger. The supplied assessment feedback conflicts with this textbook account; this exercise uses explicit relationships.',ss(1),ex(1,{media:M.intrusion,sourceFigure:true,wordBank:true}));
A.mc('e2-c9q-04',c(2),'In the original block, lava covers only part of a landscape. Which relative-age relationship does that contact establish?',['The covered surface formed after the lava|The substrate had to exist before it was covered.','The eruption and all erosion were simultaneous|The contact does not establish that.','*The covered surface existed before the lava|The lava was deposited on the older surface.','The lava predates every rock below the surface|It overlies and postdates the substrate.'],'A surface must exist before a lava flow can cover it.',ss(2),ex(2,{media:M.lava,sourceFigure:true}));
A.order('e2-c9q-05',c(3),'The original photograph labels sandstone above granite. Order the required history from oldest to youngest; the contact name is supplied, so the task tests events.',['Granite crystallizes at depth','Uplift and erosion expose the granite','Sediment is deposited on the exposed granite','The sediment becomes sandstone'],'Crystallization precedes exposure; exposure and erosion precede deposition directly on the granite.',ss(3),ex(3,{media:M.basement,sourceFigure:true}));
A.mc('e2-c9q-06',c(3),'Parallel limestone layers on either side of a contact look nearly identical. Which additional observation most directly tests for missing geologic time?',['Equal calcite content in both layers|Same mineral does not imply the same age.','Similar fractures cutting both layers|A later fracture pattern need not date deposition.','Similar pore space in both layers|Porosity is not a direct time-gap measure.','*Fossil assemblages with separated age ranges|Known fossil ranges can expose a gap despite similar lithology.'],'Fossils can constrain ages and reveal missing intervals where lithology alone is inconclusive.',['TB9:9.3','TB9:9.7'],ex(3));
A.match('e2-c9q-07',c(5),'Classify each feature by its origin. Bank terms may be reused.',[['Preserved leaf impression','Body fossil'],['Dinosaur track in sediment','Trace fossil'],['Sediment-filled animal burrow','Trace fossil'],['Branching manganese-oxide growth','Mineral growth, not a fossil']],'Body evidence and traces of biological activity are fossils; inorganic dendrites are not.',ss(5),ex(5,{wordBank:true}));
A.order('e2-c9q-08',c(8),'Arrange these broad intervals from oldest to youngest. Precambrian is used here as the broad interval before the Cambrian, not as an era equivalent.',['Precambrian','Paleozoic','Mesozoic','Cenozoic'],'Precambrian time precedes the Paleozoic, which is followed by Mesozoic and Cenozoic.',ss(8),ex(8));
A.mc('e2-c9q-09',c(8),'Which interval precedes the Cambrian expansion of abundant organisms with hard parts?',['Cenozoic|This is the youngest of these broad divisions.','Mesozoic|This follows the Paleozoic.','Paleozoic|The Cambrian begins this era.','*Precambrian|It precedes the Cambrian; life existed then too.'],'The Precambrian predates the Cambrian hard-part expansion, not all life.',['TB9:9.8','TB9:9.11'],ex(8));
A.mc('e2-c9q-10',c(7),'Two unreworked fossil species occur together in one bed. Their known time ranges overlap only briefly. What interval best constrains the bed?',['The sum of both species’ full lifespans|Ranges are not added.','*The interval shared by both species|Both must have been present when the deposit formed.','The full range of whichever lived longest|This discards the second fossil constraint.','The interval after both species disappeared|Unreworked fossils cannot have lived after extinction.'],'Use the intersection of the fossil ranges, with reworking excluded by the prompt.',ss(7),ex(7));
A.mc('e2-c9q-11',c(11),'What does “explosion” refer to in the Cambrian explosion?',['A single eruption that produced Earth’s first life|The term does not mean a volcanic eruption or life’s origin.','A meteorite impact ending the dinosaur interval|That describes a much later event.','*Rapid diversification including many hard-part organisms|It is a biological change on a geological timescale.','The disappearance of all marine organisms|It is not the extinction of all sea life.'],'The textbook describes relatively rapid diversification over millions of years, including widespread shelled organisms.',ss(11),ex(11));
A.match('e2-c9q-12',c(9),'Match each annual record to the process producing its repeated layers. Use each term once.',[['Tree-ring record','Seasonal changes in wood growth'],['Ice-core record','Yearly cycles of snow accumulation'],['Lake-varve record','Seasonal changes in sediment deposition']],'Each record can preserve annual cycles; a varve includes the seasonal pair, not one year per stripe.',ss(9),ex(9,{wordBank:true}));
A.mc('e2-c9q-13',c(9),'The textbook’s approximately 4.0-billion-year-old Canadian rocks and 4.4-billion-year-old Australian zircon grains belong to which broad interval?',['*Precambrian|These dates greatly predate the Cambrian.','Paleozoic|This era is much younger.','Mesozoic|This era is much younger.','Cenozoic|This is the youngest era listed.'],'Distinguish ancient grain age from host-rock age; both cited ages are Precambrian.',ss(9),ex(9));
A.teach('e2-c9q-14',c(10),'State the distinguishing shape feature of a complex impact crater in the textbook model, and explain why a simple crater cannot automatically be called younger.','A complex crater has a central peak; a simple crater lacks that feature in this model. The difference is related to impact size and crater formation, not a universal age order.',['Identifies the central peak of the complex crater.','Distinguishes impact size/formation geometry from age.'],ss(10),ex(10,{focusedWriting:true}));
A.mc('e2-c9q-15',c(10),'The supplied textbook identifies this finely banded specimen as iron formation, chiefly iron oxides and quartz. Which process best accounts for its formation?',['Cooling of lava exposed to air|The iron formation is not a subaerial lava flow.','Cooling of lava below the sea|The banded oxide-quartz deposit is not pillow lava.','*Oxidation and precipitation of dissolved iron in ocean water|Added oxygen caused dissolved oceanic iron to precipitate.','Oxidation of iron only within a dry land soil|The textbook places this formation in ocean water.'],'Oxygenation caused dissolved iron to oxidize and precipitate in the ocean; the original assessment picture itself is missing.',ss(10),ex(10,{media:M.iron,sourceFigure:true}));
A.fill('e2-c9q-16',c(10),'Which biological process performed by cyanobacteria supplied oxygen to Earth’s early oceans and atmosphere?',['photosynthesis'],'Photosynthesis released oxygen as a by-product, changing ocean and atmospheric chemistry.',ss(10),ex(10));
A.match('e2-c9q-17',c(12),'Match these time descriptions. Use each bank term once.',[['Era called the age of dinosaurs','Mesozoic'],['Youngest era, following the dinosaur-dominated interval','Cenozoic'],['Earliest of the three Mesozoic periods','Triassic'],['Latest of the three Mesozoic periods','Cretaceous']],'The Mesozoic contains Triassic, Jurassic and Cretaceous; the Cenozoic follows.',ss(12),ex(12,{wordBank:true}));
A.mc('e2-c9q-18',c(13),'The textbook columns have interpreted dashed correlations. If the outcrop is exposed between two sections, what field evidence would most directly verify that a bed is the same unit in both?',['Equal thickness measured at both ends|Thickness can change laterally and equal thickness is not proof.','Similar color in photographs of both ends|Unrelated units can have similar colors.','Fossils present somewhere in both sections|Fossils must be identified and interpreted, not merely present.','*Continuous physical tracing of the bed between them|This directly demonstrates lateral continuity.'],'Tracing continuity is stronger than matching appearance alone; dashed lines themselves are interpretations.',ss(13),ex(13,{media:M.correlation,sourceFigure:true}));
A.match('e2-c9q-19',c(14),'Match each archaeological or human-origins observation to a suitable dating strategy. Use each bank term once.',[['Old masonry fragments reused in a younger wall','Relative dating by inclusions'],['Undisturbed older occupation buried by a newer one','Relative dating by superposition'],['Charcoal from a site a few thousand years old','Carbon-14 dating'],['Volcanic layers bracketing million-year-old remains','Isotopic dating of volcanic minerals']],'Choose a method that fits both material and timescale; carbon-14 is not the choice for million-year-old volcanic minerals.',ss(14),ex(14,{wordBank:true}));
A.mc('e2-c9q-20',c(15),'In the textbook’s Grand Canyon history, 1.7-billion-year-old basement lies below 1.1-billion-year-old deposits at the lower unconformity. About how much time is missing there?',['60 million years|This is a factor of ten too small.','*600 million years|1.7 minus 1.1 billion years is 0.6 billion years.','1,100 million years|That is the age of the overlying deposits, not the gap.','1,700 million years|That is the basement age, not the gap.'],'The lower gap is about 600 million years. Where unconformities merge, the combined missing interval is larger.',ss(15),ex(15));
})(window.L);

