var descriptions={"E2T13": ["Deposition. Horizontal limestone layers accumulate beneath water.", "Folding. The sea retreats; compression folds the existing beds.", "Erosion. Erosion truncates different beds across a new surface.", "Burial. Younger conglomerate buries the eroded, folded beds.", "Angular unconformity. The contact records deposition, deformation, erosion and renewed deposition."], "E2T14": ["Parent isotopes. Begin with parent atoms in an ideal closed system.", "First half-life. The parent fraction falls from 100% to 50% during this interval.", "Second half-life. Half of the remaining parents decay; the endpoint is 25% parent and 75% daughter.", "Third half-life. The parent fraction falls from 25% to 12.5%; equal time removes a smaller amount.", "Read the clock. Ratios constrain age only when the dating assumptions are evaluated."], "E2T15": ["A buried shell. Rapid burial protects remains from destruction.", "Forming a mold. Dissolution removes the shell; the completed mold is a shaped cavity.", "Forming a cast. Later minerals fill the cavity; the completed cast reproduces its shape.", "Different records. A mold is an empty impression; a cast is its later infill."], "E2T16": ["An incoming impactor. An early Earth impact concentrates energy at the surface.", "Impact and excavation. Shock, fragmentation and excavation displace target material.", "Ejecta settles. Excavated material accumulates outside the crater.", "A simple crater. The depression and raised rim record impact; later erosion can remove them.", "Evidence, not a clock. Crater relations give relative order; isotopic ages add numerical constraints."], "E2T17": ["Ancient basement. Metamorphic and plutonic basement formed about 1.7 billion years ago.", "Precambrian cover. Sedimentary and volcanic cover accumulated about 1.1 billion years ago.", "Tilt and erode. Tilting and erosion removed rock and left an angular unconformity.", "Paleozoic deposition. Sandstone, shale and limestone accumulated above the eroded surface.", "Canyon incision. Much later, the river cut through the old rocks, exposing their long history.", "Two different ages. Old canyon-wall rocks do not give the age of canyon cutting."]};
function html(t){var f=films[t.id],base='videos/chapter9/'+t.id;return '<section class="card ad-video ch9-film" data-ch9-film="'+t.id+'"><p class="eyebrow">Animated geological process · timed captions</p><h2>'+esc(f.title)+'</h2><video controls playsinline preload="metadata" poster="'+base+'.png" aria-label="'+esc(f.title)+'"><source src="'+base+'.mp4" type="video/mp4">'+(typeof window.VTTCue==='function'?'':'<track kind="captions" src="'+base+'.vtt" srclang="en" label="Explanatory captions">')+'Your browser does not support video.</video><div class="row"><button class="btn pri" data-ch9-play>Play animation</button><button class="btn" data-ch9-captions aria-pressed="false">Captions: off</button>'+f.beats.map(function(b){return '<button class="btn small" data-ch9-seek="'+b[0]+'">'+esc(b[1])+'</button>';}).join('')+'<label>Speed <select data-ch9-speed aria-label="Animation speed"><option value="0.5">0.5×</option><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option></select></label></div><p>'+esc(f.limit)+'</p><details><summary>Read the stage explanations</summary>'+f.beats.map(function(b,i){var end=f.beats[i+1]?f.beats[i+1][0]:f.duration;return '<p><strong>'+b[0]+'–'+end+' seconds: '+esc(b[1])+'</strong><br>'+esc(descriptions[t.id][i])+'</p>';}).join('')+'<a href="'+base+'.txt" target="_blank" rel="noopener">Full explanation text</a></details><details><summary>Compare the original source figure</summary>'+L.itemUI.mediaHTML({kind:'img',src:L.EXAM2_SOURCES[f.section].selectedFigure.src,alt:L.EXAM2_SOURCES[f.section].selectedFigure.alt,cap:L.EXAM2_SOURCES[f.section].selectedFigure.cap})+'</details><div class="row"><button class="btn pri" data-e2-practice="'+t.id+'">Practice this topic</button><a class="btn small" download href="'+base+'.mp4">Save film</a><a class="btn small" download href="'+base+'.vtt">Save captions</a></div><p class="small muted">Silent film · '+f.duration+' seconds · local playback · watching does not change mastery.</p></section>';}
function wire(main){main.querySelectorAll('[data-ch9-film]').forEach(function(frame){var v=frame.querySelector('video'),play=frame.querySelector('[data-ch9-play]'),caps=frame.querySelector('[data-ch9-captions]');var track;if(typeof window.VTTCue==='function'&&v.addTextTrack){track=v.addTextTrack('captions','Explanatory captions','en');var f=films[frame.dataset.ch9Film];f.beats.forEach(function(b,i){var end=f.beats[i+1]?f.beats[i+1][0]-.01:f.duration;var cue=new window.VTTCue(b[0],end,descriptions[frame.dataset.ch9Film][i]);cue.line=0;cue.position=50;cue.size=90;track.addCue(cue);});track.mode='hidden';}else track=v.textTracks[0];play.onclick=function(){if(v.paused)v.play().catch(function(){play.textContent='Play animation';});else v.pause();};v.addEventListener('play',function(){play.textContent='Pause animation';});v.addEventListener('pause',function(){play.textContent='Play animation';});caps.onclick=function(){var enabled=caps.getAttribute('aria-pressed')!=='true';if(track)track.mode=enabled?'showing':'hidden';caps.setAttribute('aria-pressed',String(enabled));caps.textContent='Captions: '+(enabled?'on':'off');};frame.querySelectorAll('[data-ch9-seek]').forEach(function(b){b.onclick=function(){v.currentTime=+b.dataset.ch9Seek;};});var speed=frame.querySelector('[data-ch9-speed]');speed.onchange=function(){v.playbackRate=+speed.value;};});}
